md(68,"Hà Nội là trung tâm tài chính lớn","Hà Nội là trung tâm tài chính lớn của cả nước, nhưng hệ thống dịch vụ tài chính chưa đạt tầm khu vực. Thành phố đưa vấn đề này vào Danh mục bài toán lớn giai đoạn 2026–2030 dưới dạng bài toán số 19: “Phương thức nào để xây dựng Hà Nội thành trung tâm tài chính và dịch vụ chất lượng cao quốc tế?” (Ủy ban nhân dân thành phố Hà Nội, 2026, Phụ lục, bài toán số 19). Đề tài không đề xuất mô hình trung tâm tài chính (câu hỏi thứ nhất của bài toán) hay nền tảng công nghệ cho thị trường tài chính (câu hỏi thứ ba). Đề tài cung cấp thước đo nền cho hai câu hỏi này: chất lượng giao dịch cổ phiếu khác nhau thế nào giữa sàn niêm yết của Hà Nội và sàn của Thành phố Hồ Chí Minh, và thay đổi thế nào khi cổ phiếu niêm yết chuyển từ HNX sang HOSE.")
de(69,"Đề tài không đề xuất mô hình")
de(76,"Bằng chứng quốc tế cho thấy")
md(77,"Đợt hợp nhất ở Việt Nam","Đợt hợp nhất ở Việt Nam đổi sàn của toàn bộ cổ phiếu niêm yết tại HNX, gồm 299 mã tính đến phiên 30/9/2026 (Tuổi Trẻ Online, 2026), trong cùng một ngày. Sự kiện này cho phép so sánh cùng các cổ phiếu trước và sau khi đổi sàn với một nhóm đối chứng, về thanh khoản lẫn khả năng đầu tư.")
md(96,"Naeem (2023) hồi quy","Naeem (2023) hồi quy thứ hạng GFCI của 196 trung tâm giai đoạn 2007–2020 theo 17 yếu tố chọn bằng phương pháp cây quyết định, không gồm chỉ báo thị trường cổ phiếu; Cetorelli và Peristiani (2013) đo vị thế trung tâm qua mạng lưới niêm yết quốc tế của sàn. Ở Trung Quốc, Lai (2012) và Wang và cộng sự (2007) mô tả sự phân vai giữa Bắc Kinh, Thượng Hải và Hồng Kông, Chen và Chen (2015) nhấn mạnh vai trò dẫn dắt của nhà nước, và Elliott (2011) cho rằng không có công thức chung để xây dựng một trung tâm toàn cầu.")
md(127,"Đề tài dùng hai bộ dữ liệu","Đề tài dùng hai bộ dữ liệu. Bộ dữ liệu quốc tế cho câu hỏi 1 gồm điểm và thứ hạng GFCI các kỳ 1–40, do Z/Yen công bố công khai từ năm 2007, được thí sinh số hóa từ báo cáo từng kỳ sau khi xin phép Long Finance và ghép với các chỉ báo thị trường cổ phiếu cấp quốc gia (Čihák và cộng sự, 2012) và các chỉ số quản trị nhà nước (Kaufmann và cộng sự, 2011).")
md(128,"Bộ dữ liệu Việt Nam gồm","Bộ dữ liệu Việt Nam gồm giá điều chỉnh, khối lượng và giá trị giao dịch theo ngày của cổ phiếu trên sàn niêm yết HNX, UPCoM và HOSE, kể cả mã đã hủy niêm yết hoặc chuyển sàn, cùng các chỉ số thị trường, lợi suất trái phiếu chính phủ kỳ hạn một năm và thời điểm công bố báo cáo tài chính quý. Nguồn là HNX, HOSE và một nhà cung cấp dữ liệu thương mại; dữ liệu không chứa thông tin cá nhân.")
md(130,"Ngày cổ phiếu bị đình chỉ","Ngày bị đình chỉ giao dịch được loại khỏi mẫu số của tỷ lệ ngày lợi suất bằng 0. Độ phi thanh khoản Amihud được winsorize tại phân vị 1% và 99% tính trên mẫu gộp các sàn trong từng tháng, để ngưỡng không đổi khi cổ phiếu đổi sàn.")
md(134,"Chiều hiệu quả thông tin gồm","Chiều hiệu quả thông tin gồm độ lệch của tỷ số phương sai khỏi 1 (Lo & MacKinlay, 1988) và độ trễ giá (Hou & Moskowitz, 2005); vì hai thước đo này có thể cho kết luận sai khi môi trường thông tin khác nhau (Griffin và cộng sự, 2010), chỉ số được tính lại khi bỏ chiều này. Chiều minh bạch là số ngày trễ hạn công bố báo cáo tài chính quý.")
md(136,"Đề tài gộp các chỉ báo","Các chỉ báo được gộp thành Chỉ số chất lượng thị trường vốn theo hướng dẫn của OECD (2008). Mỗi chỉ báo được chuẩn hóa thành điểm z theo mẫu gộp các sàn trong giai đoạn tham chiếu, để giá trị đã công bố không phải tính lại, rồi đổi dấu sao cho giá trị cao hơn là chất lượng tốt hơn. Với sàn k và tháng t, chỉ số là:")
md(139,"Đề tài kiểm định H","H2 được kiểm định trên chuỗi chênh lệch chỉ số theo tháng giữa HOSE và sàn niêm yết HNX, và được ủng hộ khi chênh lệch bình quân trong giai đoạn tham chiếu dương với giá trị p bootstrap khối dừng (Politis & Romano, 1994) nhỏ hơn ngưỡng Holm tương ứng. Chênh lệch trong giai đoạn chuyển tiếp, chênh lệch giữa HOSE và UPCoM, chênh lệch theo giai đoạn căng thẳng và điểm gãy cấu trúc (Bai & Perron, 1998) được báo cáo ở dạng mô tả.")
md(141,"Đề tài đo khả năng đầu tư bằng bảy","Đề tài đo khả năng đầu tư bằng bảy mô hình phân bổ (Bảng 3), đại diện cho các hướng tiếp cận ở nhóm tài liệu (D) và cho quy tắc có trạng thái thị trường (Hamilton, 1989; Kritzman và cộng sự, 2012). Bình quân theo bảy mô hình làm kết luận ít phụ thuộc vào sai số ước lượng của một mô hình, còn độ phân tán giữa các mô hình cho biết mức phụ thuộc đó.")
rp(145,"Đề tài chọn siêu tham số",[(" Đề tài chỉ ước lượng trực tiếp M3 khi tỷ lệ số cổ phiếu trên số quan sát tuần không vượt 0,5; khi vượt ngưỡng, M3 dùng nghịch đảo giả Moore-Penrose và kết quả ghi rõ điều này.","")])
md(147,"Tệp đăng ký cố định","Tệp đăng ký cố định trước mọi lựa chọn có thể ảnh hưởng tới kết quả: chỉ báo và trọng số; quy tắc lập rổ và ghép đối chứng; chi phí giao dịch và siêu tham số của bảy mô hình; đặc tả các phương trình (5)–(7) và thủ tục suy luận; ngưỡng lợi suất khi tính Amihud; định nghĩa mức chịu cú sốc và biến trụ sở; mức ý nghĩa và cách hiệu chỉnh so sánh bội. Mọi thay đổi sau ngày đăng ký được ghi là lệch khỏi kế hoạch.")
md(151,"Đề tài dùng hai cấu hình chi phí","Đề tài dùng hai cấu hình chi phí. Cấu hình A dùng tỷ lệ cố định nhân với vòng quay danh mục. Cấu hình B dùng chi phí theo cổ phiếu và theo tháng, gồm phí giao dịch, thuế và một nửa chênh lệch mua-bán (giá chào đóng cửa nếu có, nếu không thì ước lượng theo Corwin & Schultz, 2012), nên đo thêm kênh chi phí giao dịch mà sàn tác động. Lợi suất tương đương chắc chắn là:")
md(158,"Rổ CS gồm tối đa 30","Rổ CS gồm tối đa 30 cổ phiếu chuyển sàn có giá trị giao dịch bình quân ba tháng lớn nhất tại ngày tham chiếu 30/6/2025. Rổ H gồm, cho mỗi mã của rổ CS, cổ phiếu HOSE gần nhất về vốn hóa, ngành và độ phi thanh khoản tại cùng ngày, ghép có hoàn lại. Thành phần hai rổ được giữ nguyên để so sánh cùng các cổ phiếu quanh sự kiện; vì hai rổ được lập theo cùng quy tắc, thiên lệch do thông tin lỗi thời hay hồi quy về trung bình tác động lên cả hai.")
de(159,"Giữ nguyên thành phần rổ")
md(160,"Mỗi mô hình được ước lượng","Mỗi mô hình được ước lượng trên cửa sổ 104 tuần và đánh giá trên cửa sổ 3 tháng không chồng lấn (Hình 2): 20 cửa sổ từ quý 3/2020 đến quý 2/2025 và 8 cửa sổ từ quý 1/2027 đến quý 4/2028. Cửa sổ ước lượng sau sự kiện vẫn chứa dữ liệu trước ngày chuyển sàn, nên khoảng cách của M1, mô hình không cần ước lượng tham số, được báo cáo riêng như phép so sánh sạch nhất.")
md(161,"Vì số cửa sổ ít","Vì số cửa sổ ít và lợi suất tương đương chắc chắn có phương sai lớn, H4 được báo cáo ở dạng ước lượng, kèm hiệu ứng nhỏ nhất phát hiện được tính trên dữ liệu tham chiếu.")
md(168,"trong đó A","trong đó *A*ᵢ,ₜ là logarit của độ phi thanh khoản Amihud tính trên các ngày có lợi suất tuyệt đối dưới ngưỡng chung và không liền sau một ngày vượt ngưỡng này (mục 4.3.2); *D*ᵢ bằng 1 nếu cổ phiếu chuyển sàn, tức mọi cổ phiếu niêm yết tại HNX được chuyển sang HOSE theo lịch của VNX, không chỉ các mã của rổ CS; *Post*ₜ bằng 1 từ tháng 1/2027; *α*ᵢ và *τ*ₜ là hiệu ứng cố định theo cổ phiếu và theo tháng.")
md(171,"Vì mọi cổ phiếu chuyển sàn cùng","Vì mọi cổ phiếu chuyển sàn cùng một ngày, suy luận chính dựa trên chuỗi dₜ, là chênh lệch trung bình logarit Amihud giữa cổ phiếu chuyển sàn và cổ phiếu đối chứng ghép cặp trong tháng t. Thống kê kiểm định là trung bình của dₜ sau sự kiện trừ trung bình trong cửa sổ trước. Giá trị p chính được tính bằng bootstrap tự hồi quy trên dₜ, với mô hình tự hồi quy ước lượng trên giai đoạn tham chiếu, hệ số được hiệu chỉnh độ chệch, và kích thước kiểm định được kiểm tra bằng mô phỏng trước ngày đăng ký.")
md(172,"Suy luận trên các ngày giả định","Suy luận trên các ngày giả định trong giai đoạn tham chiếu, theo tinh thần của Conley và Taber (2011), chỉ là kiểm tra bổ sung: các cửa sổ giả chồng lấn nhau, chỉ tạo khoảng sáu cửa sổ độc lập, và mô phỏng sơ bộ của thí sinh cho thấy kiểm định này bác bỏ giả thuyết gốc với tần suất cao hơn đáng kể so với mức danh nghĩa. H3 được ủng hộ khi δ âm và giá trị p bootstrap tự hồi quy nhỏ hơn ngưỡng Holm tương ứng. Phiên bản nghiên cứu sự kiện kiểm tra xu hướng song song và phản ứng trong giai đoạn chuyển tiếp:")
rp(174,"trong đó k chạy",[("các hệ số δk từ tháng","các hệ số δₖ từ tháng")])
md(176,"Bộ quy tắc của FTSE Russell","Bộ quy tắc của FTSE Russell coi cả HOSE và HNX là sàn đủ điều kiện ở Việt Nam (FTSE Russell, 2026a), nên việc đổi sàn tự nó không thay đổi tư cách được sàng lọc của một mã và không được coi là một kênh tác động qua chỉ số FTSE. Danh sách cổ phiếu đủ điều kiện, lập với dữ liệu đến ngày 30/6/2026, chỉ gồm mã niêm yết tại HOSE (FTSE Russell, 2026b) và được dùng để loại mã khỏi nhóm đối chứng; nếu mã chuyển sàn nào được đưa vào chỉ số ở các kỳ sau, δ được ước lượng thêm khi loại các mã này.")
md(178,"Giả định nhận dạng là","Giả định nhận dạng là: nếu không chuyển sàn, chênh lệch thanh khoản giữa mã chịu cú sốc mạnh và mã chịu cú sốc yếu trong nhóm chuyển sàn sẽ biến động như ở nhóm đối chứng; giả định này được kiểm tra bằng các hệ số trước sự kiện. Vì các mức chịu cú sốc có thể tương quan với nhau và với quy mô, hệ số tương tác không đo riêng tác động của từng quy tắc; mô hình có thêm tương tác với quy mô và với logarit Amihud ban đầu.")
md(179,"Mỗi hệ số tương tác được suy luận","Mỗi hệ số tương tác được suy luận như δ, vì sai số chuẩn phân cụm theo cổ phiếu bác bỏ quá thường xuyên khi cú sốc chung theo tháng tác động mạnh hơn lên mã chịu cú sốc mạnh: với từng tháng, đề tài lấy hệ số góc của logarit Amihud theo mức chịu cú sốc ở mã chuyển sàn trừ hệ số góc ở mã đối chứng, rồi áp dụng bootstrap tự hồi quy cho chuỗi này. Các hệ số tương tác, kể cả theo trụ sở, là phân tích phụ đăng ký trước, không đưa vào thủ tục Holm.")
md(182,"Chênh lệch theo trụ sở là","Chênh lệch theo trụ sở là ước lượng dị biệt trong cùng một thiết kế, không phải tác động nhân quả của vị trí trụ sở, và không đo lượng thanh khoản mà thị trường vốn Hà Nội mất, vì mọi mã đều chuyển sang HOSE. Khoảng tin cậy hẹp quanh 0 sẽ không ủng hộ vai trò của vị trí sàn khi giao dịch đã điện tử hóa toàn quốc.")
md(187,"Sai số chuẩn được phân cụm theo quốc gia","Sai số chuẩn được phân cụm theo quốc gia. Vì *SMD* thay đổi chậm, *β* chủ yếu được xác định từ biến thiên theo thời gian trong từng quốc gia. Điểm GFCI đã chứa vốn hóa, giá trị và khối lượng giao dịch cổ phiếu từ Liên đoàn các Sở Giao dịch Thế giới (3 trong 144 nhân tố của kỳ GFCI 40; Wardle & Mainelli, 2026), và trung tâm mạnh có thể kéo theo giao dịch cổ phiếu, nên *β* được gọi là liên hệ có điều kiện. H1 được ủng hộ khi *β* dương với giá trị p nhỏ hơn ngưỡng Holm tương ứng.")
md(192,"Ủy ban Chứng khoán Nhà nước cũng","Ủy ban Chứng khoán Nhà nước cũng đang nghiên cứu nới biên độ và giao dịch xuyên trưa (Thời báo Tài chính Việt Nam, 2026). Nếu các thay đổi này được áp dụng trong cửa sổ sau, ngày áp dụng được ghi là một cú sốc trùng thời gian và ước lượng được báo cáo thêm với cửa sổ sau cắt tại ngày đó.")
md(195,"Từ bằng chứng đến định hướng","**Từ bằng chứng đến định hướng cho Hà Nội.** Kết quả H1–H4 được tổng hợp cùng phép so sánh vai trò của Hà Nội với Bắc Kinh và Thượng Hải (Lai, 2012; Wang và cộng sự, 2007) và với Thành phố Hồ Chí Minh, dựa trên văn bản chính sách và dữ liệu công khai, thành định hướng chuyên môn hóa cho các thị trường mà HNX tiếp tục vận hành. Phần này là tổng hợp định tính, không kiểm định giả thuyết.")
de(196,"Hai chỉ số được công bố")
md(203,"Lực kiểm định của H","Lực kiểm định của H3 phụ thuộc chủ yếu vào số tháng trước và sau sự kiện, phương sai và mức tự tương quan của chuỗi chênh lệch theo tháng, và chỉ phụ thuộc yếu vào số cổ phiếu.")
md(205,"Chẳng hạn, với σ","Chẳng hạn, với σ = 0,2 và φ = 0,6, đề tài chỉ phát hiện được mức giảm logarit Amihud từ khoảng 0,25, tương đương độ phi thanh khoản giảm khoảng 22%. Đây là giả định minh họa; σ, φ và hiệu ứng nhỏ nhất phát hiện được sẽ được ước lượng lại từ giai đoạn tham chiếu và ghi vào tệp đăng ký.")
md(206,"H","H4 có ít cửa sổ nên chỉ được báo cáo ở dạng ước lượng, và so sánh theo hai giai đoạn căng thẳng chỉ ở dạng mô tả. Giá trị p đưa vào thủ tục Holm (1979) ở mức 5% là giá trị p một phía: phân cụm theo quốc gia cho H1, bootstrap khối dừng cho H2 và bootstrap tự hồi quy cho H3.")
md(207,"Ở H","Ở H1, đề tài kiểm tra độ vững trên mẫu các trung tâm có ít nhất năm kỳ và trên mẫu cân bằng. Vì kỳ GFCI 40 đã có nhân tố trùng với *SMD* (Wardle & Mainelli, 2026), H1 được ước lượng lại trên các kỳ không trùng lặp nếu đủ số kỳ.")
de(212,"Các mã đã tự chuyển sàn")
md(218,"+ Phạm vi nội dung","+ Phạm vi nội dung: danh mục chỉ mua là cấu hình cơ sở của bảy mô hình phân bổ. Thị trường trái phiếu và phái sinh chỉ được xét trong phần định hướng chuyên môn hóa. Đề tài không đánh giá chính sách nào khác ngoài đợt chuyển sàn và không khảo sát nhà đầu tư.")
md(219,"+ Giới hạn khác","+ Giới hạn khác: kết luận về H1 là liên hệ có điều kiện; kết luận về H3 là tác động gộp của sàn trong một sự kiện, khi các giả định ở mục 4.3.8 được thỏa mãn; kết luận về H4 chỉ áp dụng cho rổ CS.")
